/* Data is generated by compare.qmd. No network requests are needed. */
(() => {
  "use strict";
  const source = document.getElementById("comparison-data");
  if (!source) return;
  const data = JSON.parse(source.textContent);
  const from = document.getElementById("version-from");
  const to = document.getElementById("version-to");
  const showUnchanged = document.getElementById("show-unchanged");
  const results = document.getElementById("comparison-results");
  const announcement = document.getElementById("comparison-announcement");
  const link = document.getElementById("comparison-link");
  const ids = new Set(data.versions.map(version => version.id));

  function filterSections() {
    results.querySelectorAll('[data-unchanged="true"]').forEach(section => {
      section.hidden = !showUnchanged.checked;
    });
  }

  function render(updateUrl = true) {
    const comparison = data.comparisons[`${from.value}:${to.value}`];
    results.innerHTML = comparison.html;
    filterSections();
    announcement.textContent = `${from.value} to ${to.value}. ${comparison.summary}`;
    const url = new URL(window.location.href);
    url.searchParams.set("from", from.value);
    url.searchParams.set("to", to.value);
    link.href = url.href;
    // file:// readers can still compare versions if History API is restricted.
    if (updateUrl) {
      try { window.history.replaceState(null, "", url.href); } catch (_) { /* Local file. */ }
    }
  }

  function readUrl() {
    const params = new URLSearchParams(window.location.search);
    from.value = ids.has(params.get("from")) ? params.get("from") : data.defaultFrom;
    to.value = ids.has(params.get("to")) ? params.get("to") : data.defaultTo;
    render(false);
  }

  from.addEventListener("change", () => render());
  to.addEventListener("change", () => render());
  showUnchanged.addEventListener("change", filterSections);
  window.addEventListener("popstate", readUrl);
  readUrl();
})();
